{"code":"func stripTag(s: String, tag: String): String {
    if (tag.isEmpty()) {
        return s
    }
    if (s.endsWith(tag)) {
        let n = s.size - tag.size
        return s[0..n]
    }
    return s
}

main() {
    println(stripTag("file.bak.bak", ".bak") == "file.bak")
    println(stripTag("a-x-b", "-x") == "a-x-b")
}
"}

