func frequency(words: Array<String>): HashMap<String,Int64> {
 let result=HashMap<String,Int64>()
 for(word in words){let key=word.trimAscii().toAsciiLower();if(!key.isEmpty()){result[key]=(result.get(key) ?? 0)+1}}
 result
}

