{"code":"func stripEndSet(s: String, marks: String): String {
    if (marks.isEmpty()) {
        return s
    }
    let runes = s.toRuneArray()
    var end = runes.size
    while (end > 0) {
        let c = runes[end - 1]
        var found = false
        for (m in marks.toRuneArray()) {
            if (m == c) {
                found = true
                break
            }
        }
        if (!found) {
            break
        }
        end--
    }
    if (end == runes.size) {
        return s
    }
    return String(runes[0..end])
}

main() {
    println(stripEndSet("abc!!!?", "!?") == "abc")
    println(stripEndSet("水甲乙甲", "甲乙") == "水")
}
"}

